mapper.select:
SELECT tdm43_manl_org_id
  FROM tdm43_manl
 WHERE tdm43_manl_id = #{manlId}

mapper.insert:
INSERT INTO tdm45_manl_relate_ics (tdm45_manl_relate_ics_id, tdm45_manl_id, tdm45_ics_class_tree_id)
SELECT f_create_seq(), #{manlId}, #{classTreeId}
 WHERE NOT EXISTS (SELECT 1 FROM tdm45_manl_relate_ics WHERE tdm45_manl_id = #{manlId} AND tdm45_ics_class_tree_id = #{classTreeId})

INSERT INTO tdm46_manl_relate_icr (tdm46_manl_relate_icr_id, tdm46_manl_id, tdm46_icr_class_tree_id)
SELECT f_create_seq(), #{manlId}, #{classTreeId}
 WHERE NOT EXISTS (SELECT 1 FROM tdm46_manl_relate_icr WHERE tdm46_manl_id = #{manlId} AND tdm46_icr_class_tree_id = #{classTreeId})

INSERT INTO tdm47_manl_relate_dcr (tdm47_manl_relate_dcr_id, tdm47_manl_id, tdm47_dcr_class_tree_id)
SELECT f_create_seq(), #{manlId}, #{classTreeId}
 WHERE NOT EXISTS (SELECT 1 FROM tdm47_manl_relate_dcr WHERE tdm47_manl_id = #{manlId} AND tdm47_dcr_class_tree_id = #{classTreeId})

mapper.select:
SELECT sys10_file_id AS file_id, f_cdnm('TdmCheckFormType', sys10_tdm_check_form_type, sys10_parent_id, f_today()) AS tdm_check_form_type_name, sys10_file_nm AS file_name, sys10_note AS note, TO_CHAR(sys10_reg_date, 'YYYY-MM-DD') AS reg_date FROM sys10_file WHERE sys10_parent_id = #{companyId} AND sys10_tdm_check_form_type LIKE #{formType} AND CONCAT(sys10_file_nm, sys10_note) ILIKE #{searchText}
AND NOT EXISTS ( SELECT 1 FROM sys11_relate_file WHERE sys11_parent_id = #{relateId} AND sys11_file_id = sys10_file_id )
ORDER BY sys10_tdm_check_form_type , sys10_file_nm COLLATE "ko-KR-x-icu" , sys10_note COLLATE "ko-KR-x-icu" , sys10_reg_date

SELECT row_number() over() AS manl_id , t.tdm43_manl_org_id AS manl_org_id , t.tdm43_org_id AS org_id , t.tdm43_role_id AS role_id , t.tdm43_task_nm AS task_name , t.tdm43_task_relate_detail_id AS task_relate_detail_id , t.tdm43_task_relate_detail_nm AS task_relate_detail_name , t.tdm43_task_relate_duty_id AS task_relate_duty_id , t.tdm43_task_relate_duty_nm AS task_relate_duty_name , t.tdm43_org_nm AS org_name , TO_CHAR(t.tdm43_apply_start_date, 'YYYY-MM-DD') AS apply_start_date , TO_CHAR(t.tdm43_apply_end_date, 'YYYY-MM-DD') AS apply_end_date , t.tdm43_job_nm AS job_name FROM ( SELECT DISTINCT tdm43_manl_org_id , tdm43_org_id , tdm43_role_id , tdm43_task_nm , tdm43_task_relate_detail_id , tdm43_task_relate_detail_nm , tdm43_task_relate_duty_id , tdm43_task_relate_duty_nm , org00_kor_nm AS tdm43_org_nm , tdm42_start_date AS tdm43_apply_start_date , tdm42_end_date AS tdm43_apply_end_date , tdm40_job_nm AS tdm43_job_nm FROM tdm42_manl_org INNER JOIN tdm43_manl ON tdm43_manl_org_id = tdm42_manl_org_id INNER JOIN tdm40_manl_job ON tdm40_manl_job_id = tdm42_manl_job_id INNER JOIN getOrg(#{companyId}, #{stdDate}::date) ON org00_org_id = tdm43_org_id WHERE tdm42_company_id = #{companyId} AND tdm42_lock_yn = 'true'
AND tdm42_role_id = #{roleId}
AND tdm42_org_id = #{orgId}
AND tdm43_task_id = #{taskId}
AND #{stdDate}::date BETWEEN tdm42_start_date AND COALESCE(tdm42_end_date,'9999-12-31'::date)
) t WHERE CONCAT(tdm43_org_nm, tdm43_task_nm, tdm43_task_relate_detail_nm, tdm43_task_relate_duty_nm) ILIKE #{searchText} ORDER BY tdm43_task_nm COLLATE "ko_KR.utf8" , tdm43_task_relate_detail_nm COLLATE "ko_KR.utf8" , tdm43_task_relate_duty_nm COLLATE "ko_KR.utf8" , tdm43_org_nm COLLATE "ko_KR.utf8" , tdm43_apply_start_date

SELECT row_number() over() AS manl_id , t.tdm43_manl_org_id AS manl_org_id , t.tdm43_org_id AS org_id , t.tdm43_role_id AS role_id , t.tdm43_role_nm AS role_name , t.tdm43_task_id AS task_id , t.tdm43_task_nm AS task_name , t.tdm43_task_relate_detail_id AS task_relate_detail_id , t.tdm43_task_relate_detail_nm AS task_relate_detail_name , t.tdm43_task_relate_duty_id AS task_relate_duty_id , t.tdm43_task_relate_duty_nm AS task_relate_duty_name , t.tdm43_org_nm AS org_name , TO_CHAR(t.tdm43_apply_start_date, 'YYYY-MM-DD') AS apply_start_date , TO_CHAR(t.tdm43_apply_end_date, 'YYYY-MM-DD') AS apply_end_date , t.tdm43_job_nm AS job_name FROM ( SELECT DISTINCT tdm43_manl_org_id , tdm43_org_id , tdm43_role_id , tdm20_role_nm AS tdm43_role_nm , tdm43_task_id , tdm43_task_nm , tdm43_task_relate_detail_id , tdm43_task_relate_detail_nm , tdm43_task_relate_duty_id , tdm43_task_relate_duty_nm , org00_kor_nm AS tdm43_org_nm , tdm42_start_date AS tdm43_apply_start_date , tdm42_end_date AS tdm43_apply_end_date , tdm40_job_nm AS tdm43_job_nm , tdm43_company_id FROM tdm42_manl_org INNER JOIN tdm43_manl ON tdm43_manl_org_id = tdm42_manl_org_id INNER JOIN tdm40_manl_job ON tdm40_manl_job_id = tdm42_manl_job_id INNER JOIN LATERAL getOrg(#{companyId}, tdm42_start_date) ON org00_org_id = tdm42_org_id INNER JOIN tdm20_role ON tdm20_role_id = tdm43_role_id WHERE tdm42_company_id = #{companyId} AND tdm42_lock_yn = 'true'
AND tdm42_role_id = #{roleId}
AND tdm43_task_id = #{taskId}
AND tdm43_org_id = #{orgId}
AND #{stdDate}::date BETWEEN tdm42_start_date AND COALESCE(tdm42_end_date,'9999-12-31'::date)
AND EXISTS ( /*이번 작업에 점검항목을 작성해야할 우리 부서의 관리의무 리스트 */ SELECT 1 FROM tdm41_manl_duty INNER JOIN tdm44_manl_duty_org ON tdm44_manl_duty_id = tdm41_manl_duty_id WHERE tdm41_manl_job_id = #{manlJobId} AND tdm41_role_id = #{stdRoleId} AND tdm44_org_id = #{stdOrgId} AND tdm41_task_relate_duty_id = tdm43_task_relate_duty_id ) ) t WHERE CONCAT(tdm43_task_nm, tdm43_task_relate_detail_nm, tdm43_task_relate_duty_nm, tdm43_org_nm) ILIKE #{searchText} ORDER BY tdm43_task_nm COLLATE "ko_KR.utf8" , tdm43_task_relate_detail_nm COLLATE "ko_KR.utf8" , tdm43_task_relate_duty_nm COLLATE "ko_KR.utf8" , tdm43_org_nm COLLATE "ko_KR.utf8" , tdm43_apply_start_date

SELECT COUNT(*)
  FROM tdm43_manl
 WHERE tdm43_manl_org_id = #{manlOrgId}
   AND tdm43_manl_cd     = #{manlCode}

mapper.insert:
INSERT
  INTO  tdm43_manl
SELECT  #{newManlId}
     ,  #{req.manlOrgId}
     ,  tdm43_company_id
     ,  #{req.orgId}
     ,  #{req.exctId}
     ,  #{req.roleId}
     ,  #{req.roleName}
     ,  #{req.taskId}
     ,  #{req.taskName}
     ,  #{req.taskRelateDetailId}
     ,  #{req.taskRelateDetailName}
     ,  #{req.taskRelateDutyId}
     ,  #{req.taskRelateDutyName}
     ,  tdm43_check_item
     ,  tdm43_check_cycle_cd
     ,  tdm43_check_month
     ,  null
     ,  null
     ,  tdm43_check_how
     ,  tdm43_ref_basis
     ,  tdm43_start_date
     ,  #{req.manlDutyId}
     ,  #{firstRegEmpId}
     ,  CASE WHEN #{req.orgId} = tdm43_org_id THEN tdm43_manl_cd
             ELSE (
                    SELECT TO_CHAR(NOW(),'YY')||
                           LPAD((COALESCE( (SELECT SUBSTR(MAX(b.tdm43_manl_cd),3)::numeric
                                              FROM tdm43_manl b
                                             WHERE b.tdm43_company_id = a.tdm43_company_id
                                               AND SUBSTR(b.tdm43_manl_cd,1,2) = TO_CHAR(NOW(),'YY')), 0) + 1)::text, 5, '0')
                  ) END
     ,  #{updName}
     ,  f_sysdate()
     ,  tdm43_check_evid_doc_nm
     ,  tdm43_ceo_duty_cd
     ,  null
     ,  tdm43_import_level_cd
     ,  tdm43_exct_duty_map
  FROM  tdm43_manl a
 WHERE  tdm43_manl_id = #{manlId}

mapper.select:
SELECT t.tdm43_manl_id AS manl_id, t.tdm43_manl_org_id AS manl_org_id, t.tdm43_company_id AS company_id, t.tdm43_org_id AS org_id, t.tdm43_exct_id AS exct_id, t.tdm43_role_id AS role_id, t.tdm43_role_nm AS role_name, t.tdm43_task_id AS task_id, t.tdm43_task_nm AS task_name, t.tdm43_task_relate_detail_id AS task_relate_detail_id, t.tdm43_task_relate_detail_nm AS task_relate_detail_name, t.tdm43_task_relate_duty_id AS task_relate_duty_id, t.tdm43_task_relate_duty_nm AS task_relate_duty_name, t.tdm43_manl_duty_id AS manl_duty_id, t.tdm43_manl_cd AS manl_code, t.tdm43_check_item AS check_item, CASE WHEN t.tdm43_manl_cd IS NULL THEN NULL ELSE '(' || t.tdm43_manl_cd || ') ' || t.tdm43_check_item END AS check_item_add_code, t.tdm43_check_cycle_cd AS check_cycle_code, t.tdm43_check_month AS check_month, t.tdm43_check_how AS check_how, t.tdm43_check_evid_doc_nm AS check_evid_doc_name, t.tdm43_ref_basis AS ref_basis, TO_CHAR(t.tdm43_start_date, 'YYYY-MM-DD') AS start_date, t.tdm43_ceo_duty_cd AS ceo_duty_code, f_cdnm('TdmCeoDutyCode', t.tdm43_ceo_duty_cd, t.tdm43_company_id, f_sysdate()) AS ceo_duty_name, t.tdm43_exct_duty_map AS exct_duty_map, f_get_exctDutyMap_nm(t.tdm43_exct_duty_map) AS exct_duty_name, t.tdm43_import_level_cd AS import_level_code, f_cdnm('TdmImportLevelCode', t.tdm43_import_level_cd, t.tdm43_company_id, f_sysdate()) AS import_level_name, CASE WHEN ( t.tdm43_start_date IS NULL OR t.tdm43_start_date <= #{stdDate}::date ) THEN false ELSE true END AS unuse_yn, t.tdm43_org_nm AS org_name, t.tdm43_job_nm AS job_name, CASE WHEN COALESCE(t.ics_cnt, 0) = 0 THEN '' ELSE t.ics_cnt || '건' END AS ics_cnt_str, CASE WHEN COALESCE(t.icr_cnt, 0) = 0 THEN '' ELSE t.icr_cnt || '건' END AS icr_cnt_str, CASE WHEN COALESCE(t.formfile_cnt, 0) = 0 THEN '' ELSE t.formfile_cnt || '건' END AS form_file_cnt_str, CASE WHEN COALESCE(t.dcr_cnt, 0) = 0 THEN '' ELSE t.dcr_cnt || '건' END AS dcr_cnt_str FROM ( SELECT tdm43_manl.* , org00_kor_nm AS tdm43_org_nm , tdm40_job_nm AS tdm43_job_nm , (SELECT COUNT(*) FROM tdm45_manl_relate_ics WHERE tdm45_manl_id = tdm43_manl_id) AS ics_cnt , (SELECT COUNT(*) FROM tdm46_manl_relate_icr WHERE tdm46_manl_id = tdm43_manl_id) AS icr_cnt , (SELECT COUNT(*) FROM sys11_relate_file WHERE sys11_parent_id = tdm43_manl_id) AS formfile_cnt , (SELECT COUNT(*) FROM tdm47_manl_relate_dcr WHERE tdm47_manl_id = tdm43_manl_id) AS dcr_cnt FROM tdm42_manl_org INNER JOIN tdm40_manl_job ON tdm40_manl_job_id = tdm42_manl_job_id INNER JOIN tdm43_manl ON tdm43_manl_org_id = tdm42_manl_org_id INNER JOIN getOrg(#{companyId}, #{stdDate}::date) ON org00_org_id = tdm43_org_id WHERE tdm42_company_id = #{companyId} AND #{stdDate}::date BETWEEN tdm42_start_date AND COALESCE(tdm42_end_date, '2999-12-31'::date) AND CONCAT(tdm43_role_nm, org00_kor_nm, tdm43_task_relate_duty_nm, tdm43_manl_cd, tdm43_check_item) ILIKE #{searchText} ) t WHERE 1=1
AND t.tdm43_manl_id = #{manlId}
ORDER BY t.tdm43_role_nm COLLATE "ko_KR.utf8" , t.tdm43_org_nm COLLATE "ko_KR.utf8" , t.tdm43_task_nm COLLATE "ko_KR.utf8" , t.tdm43_task_relate_detail_nm COLLATE "ko_KR.utf8" , t.tdm43_task_relate_duty_nm COLLATE "ko_KR.utf8" , t.tdm43_manl_cd

mapper.update:
UPDATE tdm43_manl
   SET tdm43_ceo_duty_cd        = #{req.ceoDutyCode}
     , tdm43_exct_duty_map      = #{req.exctDutyMap}
     , tdm43_import_level_cd    = #{req.importLevelCode}
     , tdm43_start_date         = CAST(#{req.startDate, jdbcType=VARCHAR} AS date)
     , tdm43_check_evid_doc_nm  = #{req.checkEvidDocName}
     , tdm43_upd_nm             = #{updName}
     , tdm43_upd_date           = f_sysdate()
 WHERE tdm43_manl_id = #{manlId}

UPDATE tdm43_manl
   SET tdm43_ref_basis = #{refBasis}
     , tdm43_upd_nm    = #{updName}
     , tdm43_upd_date  = f_sysdate()
 WHERE tdm43_manl_id = #{manlId}
